def project(raw):
    if dict(bytes=len(raw),sha256=hashlib.sha256(raw).hexdigest())!=CORE_PIN:raise ValueError('whole frozen strict native349 helper')
    text=raw.decode()
    for before,after in SEAMS:
        if text.count(before)!=1 or after in text:raise ValueError('one exact Fish operand')
        text=text.replace(before,after)
    reverse=text
    for before,after in reversed(SEAMS):reverse=reverse.replace(after,before)
    if reverse.encode()!=raw:raise ValueError('whole unchanged strict helper inverse')
    return text.encode()


# Keep the admission corrections separate from the five existing Fish operands.
# An independently reviewed common correction can replace this one projection.
ADMISSION_FIXES = (
    ("        if runner is not None: return runner(argv, clean)\n",
     "        cap = min(seconds, deadline-time.monotonic())\n"
     "        need(cap > 1, 'fetch-command-budget-before-spawn')\n"
     "        if runner is not None: return runner(argv, clean)\n"),
    ("        row = owned.supervise(child, cap=min(seconds, deadline-time.monotonic()), retirement=1, grace=.1, max_output=1024**2)\n",
     "        cap = min(cap, deadline-time.monotonic())\n"
     "        expired = cap <= 1\n"
     "        # Always transfer a spawned child to valid bounded retirement.\n"
     "        row = owned.supervise(child, cap=1.001 if expired else cap, retirement=1, grace=.1, max_output=1024**2)\n"),
    ("        need(row['exit'] == 0 and row['reaped'] and row['ownership'] == 'REAPED' and row['group_census'] == 'EMPTY_TWICE'\n",
     "        need(not expired, 'fetch-command-budget-after-spawn')\n"
     "        need(row['exit'] == 0 and row['reaped'] and row['ownership'] == 'REAPED' and row['group_census'] == 'EMPTY_TWICE'\n"),
    ("             and secret.rstrip().endswith('-----END OPENSSH PRIVATE KEY-----'), 'Root-deploy-key-required')\n",
     "             and secret.removesuffix('\\n').endswith('\\n-----END OPENSSH PRIVATE KEY-----'), 'Root-deploy-key-required')\n"
     "        if not secret.endswith('\\n'):\n"
     "            need(len(secret) < 32768, 'bounded-normalized-deploy-key')\n"
     "            secret += '\\n'\n"),
)


def correct_admission(raw):
    text = raw.decode()
    for before, after in ADMISSION_FIXES:
        if text.count(before) != 1 or after in text:
            raise ValueError('one exact carrier admission correction seam')
        text = text.replace(before, after, 1)
    corrected = text.encode()
    for before, after in reversed(ADMISSION_FIXES):
        text = text.replace(after, before, 1)
    if text.encode() != raw:
        raise ValueError('whole carrier admission correction inverse')
    return corrected


N=ModuleType('fish02_exact_carrier_core');N.__file__=str(Path(__file__).resolve());exec(compile(correct_admission(project(CORE)),N.__file__,'exec'),N.__dict__)
