LIBFFI_PACKAGE = 'libffi-3.8.0-1-aarch64.pkg.tar.xz'
LIBFFI_NAMES = frozenset((LIBFFI_PACKAGE, LIBFFI_PACKAGE + '.sig'))
LIBFFI_PRIMARY = 'https://ca.us.mirror.archlinuxarm.org/aarch64/core/'
LIBFFI_ARCHIVE = 'https://pkgmirror.sametimetomorrow.net/aarch64/packages/l/libffi/'


def install_libffi_fallback(native):
    """Reuse the pinned downloader for one archive attempt after an exact primary 404."""
    original = native.fetch
    archive_lane = threading.Lock()

    def fetch(item, cache):
        try:
            return original(item, cache)
        except native.AcquisitionError as error:
            name = item['filename']
            if (name not in LIBFFI_NAMES or item['url'] != LIBFFI_PRIMARY + name or
                    error.filename != name or error.category != 'HTTP failure' or error.http_status != 404):
                raise
        with archive_lane:
            return original(dict(item, url=LIBFFI_ARCHIVE + name), cache)

    native.fetch = fetch


def project_entry(raw):
    prior=_ORIGINAL_PROJECT_ENTRY(raw)
    before=b'len(self.rows)<160';after=b'len(self.rows)<512'
    N.need(prior.count(before)==1 and after not in prior,'one finite512 held-command seam')
    result=prior.replace(before,after)
    N.need(result.replace(after,before)==prior,'whole original held command guard inverse')
    before = b"C.audit_adapter(native,C.read(HERE/'runtime/scripts/ci/native_arm.py'))"
    after = before + b';PINNED_CARRIER.install_libffi_fallback(native)'
    N.need(result.count(before) == 1 and after not in result, 'one held acquisition fallback seam')
    projected = result.replace(before, after, 1)
    N.need(projected.replace(after, before, 1) == result, 'whole held acquisition fallback inverse')
    return projected

